import { useState, useEffect, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Package } from 'lucide-react'
import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearTable, type SortField, type SortDirection } from '@/components/gear/GearTable'
import { GearCard } from '@/components/gear/GearCard'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function GearPage() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = localStorage.getItem('gearViewMode')
    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return (saved as ViewMode) || (isMobile ? 'comfortable' : 'default')
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(() => {
    const saved = localStorage.getItem('gearWeightUnit')
    return (saved as WeightUnit) || 'g'
  })
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)
  const [sortField, setSortField] = useState<SortField>('name')
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')


  // Save view mode preference
  useEffect(() => {
    localStorage.setItem('gearViewMode', viewMode)
  }, [viewMode])

  // Save weight unit preference
  useEffect(() => {
    localStorage.setItem('gearWeightUnit', weightUnit)
  }, [weightUnit])

  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)
      )
    }

    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }

    return filtered
  }, [items, searchTerm, selectedCategory])

  // Sort filtered items with memoization
  const sortedItems = useMemo(() => {
    const sorted = [...filteredItems].sort((a, b) => {
      let aValue: string | number = a[sortField as keyof GearItem] as string | number
      let bValue: string | number = b[sortField as keyof GearItem] as string | number

      // Handle 'total' which is calculated
      if (sortField === 'total') {
        aValue = a.weight_grams * a.quantity
        bValue = b.weight_grams * b.quantity
      }

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1

      // Handle string comparison
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }

      // Handle number comparison
      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortDirection === 'asc'
          ? aValue - bValue
          : bValue - aValue
      }

      // Mixed types - convert to string for comparison
      const aStr = String(aValue)
      const bStr = String(bValue)
      return sortDirection === 'asc'
        ? aStr.localeCompare(bStr)
        : bStr.localeCompare(aStr)
    })

    return sorted
  }, [filteredItems, sortField, sortDirection])

  const handleSort = useCallback((field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDirection('asc')
    }
  }, [sortField])

  // Calculate stats with memoization
  const { totalWeight, baseWeight, categories, categoryCounts } = useMemo(() => {
    const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const baseWeight = items
      .filter(item => !item.worn && !item.consumable)
      .reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const categories = Array.from(new Set(items.map(item => item.category)))

    // Calculate category counts for dropdown
    const categoryCounts = items.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    return { totalWeight, baseWeight, categories, categoryCounts }
  }, [items])


  const handleAdd = useCallback(async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    if (!user) return

    try {
      await createGearMutation.mutateAsync(gear)
      setShowAddForm(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to add gear:', error)
    }
  }, [user, createGearMutation])

  const handleUpdate = useCallback(async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return

    try {
      await updateGearMutation.mutateAsync({ id, updates })
      setEditingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to update gear:', error)
    }
  }, [user, updateGearMutation])

  const handleDelete = useCallback(async (id: string) => {
    if (!user) return

    try {
      await deleteGearMutation.mutateAsync(id)
      setDeletingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to delete gear:', error)
      setDeletingItem(null) // Still close the dialog
    }
  }, [user, deleteGearMutation])

  const renderItems = useCallback((items: GearItem[], currentViewMode?: string) => {
    const mode = (currentViewMode || viewMode) as ViewMode

    if (mode === 'comfortable') {
      return (
        <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
          {items.map(item => (
            <GearCard
              key={item.id}
              item={item}
              weightUnit={weightUnit}
              onEdit={() => setEditingItem(item)}
              onDelete={() => setDeletingItem(item)}
            />
          ))}
        </div>
      )
    }

    return (
      <GearTable
        items={items}
        viewMode={mode}
        weightUnit={weightUnit}
        onEdit={setEditingItem}
        onDelete={setDeletingItem}
        sortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
      />
    )
  }, [viewMode, weightUnit, sortField, sortDirection, handleSort])

  const renderModals = useCallback(() => (
    <>
      {/* Add Gear Form Modal */}
      <AddGearFormWrapper
        isOpen={showAddForm}
        onAdd={handleAdd}
        onCancel={() => setShowAddForm(false)}
      />

      {/* Edit Gear Form Modal */}
      {editingItem && (
        <EditGearForm
          item={editingItem}
          onUpdate={handleUpdate}
          onCancel={() => setEditingItem(null)}
        />
      )}

      {/* Delete Confirmation Dialog */}
      {deletingItem && (
        <DeleteDialog
          item={deletingItem}
          onConfirm={() => handleDelete(deletingItem.id)}
          onCancel={() => setDeletingItem(null)}
        />
      )}
    </>
  ), [showAddForm, editingItem, deletingItem, handleAdd, handleUpdate, handleDelete])

  return (
    <CollectionPage<GearItem>
      items={items}
      filteredItems={sortedItems}
      loading={loading}
      title="Gear Closet"
      backTo="/dashboard"
      searchTerm={searchTerm}
      onSearchChange={setSearchTerm}
      searchPlaceholder="Search gear..."
      primaryFilter={{
        options: categories.map(category => ({
          value: category,
          label: category,
          count: categoryCounts[category]
        })),
        selectedValue: selectedCategory,
        onSelectValue: setSelectedCategory,
        placeholder: 'All Categories',
        allItemsLabel: 'All Categories',
        totalItems: items.length,
        mobileFilterOptions: categories.map(category => ({
          value: category,
          label: category,
          count: categoryCounts[category]
        }))
      }}
      stats={{
        itemCount: items.length,
        itemLabel: 'items',
        additionalInfo: ` • ${formatWeightWithUnit(totalWeight, weightUnit)} total • ${formatWeightWithUnit(baseWeight, weightUnit)} base`
      }}
      viewMode={{
        current: viewMode,
        onChange: setViewMode,
        component: (
          <ViewModeSelector
            value={viewMode}
            onChange={setViewMode}
          />
        )
      }}
      secondaryControls={
        <div className="hidden sm:flex gap-2">
          <WeightUnitSelector value={weightUnit} onChange={setWeightUnit} />
        </div>
      }
      emptyState={{
        icon: <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />,
        title: 'No gear found',
        description: 'Try adjusting your filters',
        noItemsTitle: 'No gear yet',
        noItemsDescription: 'Get started by adding your first item',
        showAddButton: true,
        addButtonText: 'Add First Item'
      }}
      renderItems={renderItems}
      onAdd={() => setShowAddForm(true)}
      renderModals={renderModals}
      showFloatingActionButton={true}
    />
  )
}

import { memo, useMemo } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Edit2, Trash2, MoreHorizontal, Copy, ChevronUp, ChevronDown, ChevronsUpDown, FileText } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'
import type { ViewMode } from '@/pages/GearPage'

export type SortField = 'name' | 'category' | 'weight_grams' | 'quantity' | 'total'
export type SortDirection = 'asc' | 'desc'

interface GearTableProps {
  items: GearItem[]
  viewMode: ViewMode
  weightUnit?: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  sortField?: SortField
  sortDirection?: SortDirection
  onSort?: (field: SortField) => void
}

export const GearTable = memo(function GearTable({ 
  items, 
  viewMode, 
  weightUnit = 'g',
  onEdit, 
  onDelete, 
  sortField,
  sortDirection,
  onSort 
}: GearTableProps) {
  const isCompact = viewMode === 'compact'

  // Memoize summary calculations
  const { totalWeight, totalQuantity, totalCombinedWeight } = useMemo(() => ({
    totalWeight: items.reduce((sum, item) => sum + item.weight_grams, 0),
    totalQuantity: items.reduce((sum, item) => sum + item.quantity, 0),
    totalCombinedWeight: items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
  }), [items])

  const getSortIcon = (field: SortField) => {
    if (sortField !== field) {
      return <ChevronsUpDown className="ml-1 h-3 w-3 text-muted-foreground/50" />
    }
    return sortDirection === 'asc' 
      ? <ChevronUp className="ml-1 h-3 w-3" />
      : <ChevronDown className="ml-1 h-3 w-3" />
  }

  return (
    <div className="bg-white rounded-lg border border-border/40 overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow className={isCompact ? 'h-8' : 'h-10'}>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50`}
              onClick={() => onSort?.('name')}
            >
              <div className="flex items-center">
                Item
                {getSortIcon('name')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('category')}
            >
              <div className="flex items-center">
                Category
                {getSortIcon('category')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('weight_grams')}
            >
              <div className="flex items-center justify-end">
                Weight
                {getSortIcon('weight_grams')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('quantity')}
            >
              <div className="flex items-center justify-end">
                Qty
                {getSortIcon('quantity')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden md:table-cell`}
              onClick={() => onSort?.('total')}
            >
              <div className="flex items-center justify-end">
                Total
                {getSortIcon('total')}
              </div>
            </TableHead>
            {!isCompact && (
              <TableHead className="text-sm font-medium hidden sm:table-cell">
                Properties
              </TableHead>
            )}
            <TableHead className="text-right">
              <span className="sr-only">Actions</span>
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {items.map((item) => (
            <TableRow 
              key={item.id} 
              className={`hover:bg-accent/50 transition-colors ${
                isCompact ? 'h-10' : 'h-14'
              }`}
            >
              <TableCell className={isCompact ? 'py-1' : 'py-2'}>
                <div className={isCompact ? 'space-y-0' : 'space-y-1'}>
                  <div className={`${isCompact ? 'text-sm' : 'text-base'}`}>
                    {item.name}
                  </div>
                  {(item.model || item.description) && (
                    <div className={`text-muted-foreground ${isCompact ? 'text-xs' : 'text-sm'}`}>
                      {item.model || item.description}
                    </div>
                  )}
                  {!isCompact && item.brand && (
                    <div className="text-xs text-muted-foreground">
                      {item.brand}
                    </div>
                  )}
                  {/* Mobile-only: Show category, weight, and properties inline */}
                  <div className="sm:hidden text-xs text-muted-foreground mt-1">
                    {item.category} • {formatWeightWithUnit(item.weight_grams, weightUnit)}
                    {item.worn && <span> • Worn</span>}
                    {item.consumable && <span> • Consumable</span>}
                  </div>
                </div>
              </TableCell>
              <TableCell className={`${isCompact ? 'py-1' : 'py-2'} hidden sm:table-cell`}>
                <Badge variant="outline" className={isCompact ? 'text-xs py-0' : ''}>
                  {item.category}
                </Badge>
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden sm:table-cell`}>
                {formatWeightWithUnit(item.weight_grams, weightUnit)}
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden sm:table-cell`}>
                {item.quantity}
              </TableCell>
              <TableCell className={`text-right font-medium ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden md:table-cell`}>
                {formatWeightWithUnit(item.weight_grams * item.quantity, weightUnit)}
              </TableCell>
              {!isCompact && (
                <TableCell className="py-2 hidden sm:table-cell">
                  <div className="flex items-center gap-1">
                    {item.worn && (
                      <Badge variant="secondary" className="text-xs">
                        Worn
                      </Badge>
                    )}
                    {item.consumable && (
                      <Badge variant="secondary" className="text-xs">
                        Consumable
                      </Badge>
                    )}
                    {item.notes ? (
                      <div className="group relative">
                        <FileText className="h-3 w-3 text-muted-foreground cursor-help" />
                        <div className="absolute z-10 hidden group-hover:block bottom-full left-0 mb-2 w-64 p-2 bg-popover text-popover-foreground text-xs rounded-md shadow-md border">
                          {item.notes}
                        </div>
                      </div>
                    ) : null}
                  </div>
                </TableCell>
              )}
              <TableCell className={`text-right ${isCompact ? 'py-1' : 'py-2'}`}>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button
                      variant="ghost"
                      size={isCompact ? 'sm' : 'default'}
                      className="h-8 w-8 p-0"
                    >
                      <span className="sr-only">Open menu</span>
                      <MoreHorizontal className={isCompact ? 'h-3 w-3' : 'h-4 w-4'} />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem 
                      onClick={() => onEdit(item)}
                      className="cursor-pointer"
                    >
                      <Edit2 className="mr-2 h-4 w-4" />
                      Edit
                    </DropdownMenuItem>
                    <DropdownMenuItem 
                      onClick={() => {
                        // Clone functionality - use object destructuring for type safety
                        const { id, created_at, updated_at, user_id, ...cloneData } = item
                        // Create a new item with the cloned data
                        const newItem: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'> = cloneData
                        // Since we're using onEdit for duplicate, we need to pass a full GearItem
                        // The parent will handle this as a create operation
                        onEdit({ ...newItem, name: `${newItem.name} (Copy)` } as GearItem)
                      }}
                      className="cursor-pointer"
                    >
                      <Copy className="mr-2 h-4 w-4" />
                      Duplicate
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      onClick={() => onDelete(item)}
                      className="cursor-pointer text-destructive focus:text-destructive"
                    >
                      <Trash2 className="mr-2 h-4 w-4" />
                      Delete
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </TableCell>
            </TableRow>
          ))}
          {/* Summary Row */}
          {items.length > 0 && (
            <TableRow className="bg-muted/50 border-t-2 font-medium">
              <TableCell className={`${isCompact ? 'py-2 text-sm' : 'py-3'}`}>
                Total ({items.length} items)
              </TableCell>
              <TableCell className="hidden sm:table-cell" />
              <TableCell className={`text-right ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden sm:table-cell`}>
                {formatWeightWithUnit(totalWeight, weightUnit)}
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden sm:table-cell`}>
                {totalQuantity}
              </TableCell>
              <TableCell className={`text-right font-semibold ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden md:table-cell`}>
                {formatWeightWithUnit(totalCombinedWeight, weightUnit)}
              </TableCell>
              {!isCompact && <TableCell className="hidden sm:table-cell" />}
              <TableCell />
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
})

import { useState, useMemo, useCallback, useEffect } from 'react'
