import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { MoreHorizontal } from 'lucide-react'

export interface RowAction {
  label: string
  icon: ReactNode
  onClick: () => void
  variant?: 'default' | 'destructive'
  separator?: boolean
}

export interface RowBadge {
  label: string
  variant?: 'default' | 'secondary' | 'destructive' | 'outline'
}

export interface GenericRowProps {
  title: string
  subtitle?: string
  description?: string
  badges?: RowBadge[]
  metadata?: string
  actions: RowAction[]
  onClick?: () => void
  className?: string
}

export function GenericRow({
  title,
  subtitle,
  description,
  badges = [],
  metadata,
  actions,
  onClick,
  className = ''
}: GenericRowProps) {
  const handleRowClick = (e: React.MouseEvent) => {
    // Don't trigger onClick if clicking on dropdown trigger
    if ((e.target as Element).closest('[data-dropdown-trigger]')) {
      return
    }
    onClick?.()
  }

  return (
    <div 
      className={`
        flex items-start justify-between p-4 border border-border rounded-lg 
        hover:bg-muted/50 transition-colors
        ${onClick ? 'cursor-pointer' : ''}
        ${className}
      `}
      onClick={handleRowClick}
    >
      {/* Main Content */}
      <div className="flex-1 min-w-0 space-y-2">
        {/* Title Row */}
        <div className="flex items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <h3 className="font-medium text-base leading-tight">
              {title}
            </h3>
            {subtitle && (
              <p className="text-sm text-muted-foreground mt-0.5 leading-tight">
                {subtitle}
              </p>
            )}
          </div>

          {/* Desktop Badges */}
          {badges.length > 0 && (
            <div className="hidden sm:flex items-center gap-1 flex-shrink-0">
              {badges.map((badge, index) => (
                <Badge key={index} variant={badge.variant || 'outline'} className="text-xs">
                  {badge.label}
                </Badge>
              ))}
            </div>
          )}
        </div>

        {/* Description */}
        {description && (
          <p className="text-sm text-muted-foreground leading-tight">
            {description}
          </p>
        )}

        {/* Mobile Info Line */}
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          {/* Mobile Badges */}
          {badges.length > 0 && (
            <div className="sm:hidden flex items-center gap-1">
              {badges.map((badge, index) => (
                <Badge key={index} variant={badge.variant || 'outline'} className="text-xs py-0">
                  {badge.label}
                </Badge>
              ))}
            </div>
          )}

          {/* Metadata */}
          {metadata && (
            <>
              {badges.length > 0 && <span className="sm:hidden">•</span>}
              <span>{metadata}</span>
            </>
          )}
        </div>
      </div>

      {/* Actions Menu */}
      <div className="flex-shrink-0 ml-4">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              className="h-8 w-8 p-0 hover:bg-accent"
              data-dropdown-trigger="true"
              onClick={(e) => e.stopPropagation()}
            >
              <span className="sr-only">Open menu</span>
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-[160px]">
            {actions.map((action, index) => (
              <div key={index}>
                {action.separator && index > 0 && <DropdownMenuSeparator />}
                <DropdownMenuItem
                  onClick={(e) => {
                    e.stopPropagation()
                    action.onClick()
                  }}
                  className={`cursor-pointer ${
                    action.variant === 'destructive' 
                      ? 'text-destructive focus:text-destructive' 
                      : ''
                  }`}
                >
                  <span className="mr-2">{action.icon}</span>
                  {action.label}
                </DropdownMenuItem>
              </div>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  )
}

