import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onClick?: (item: GearItem) => void
}

export function GearRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onClick 
}: GearRowProps) {
  // Build subtitle from brand, model, description
  const subtitle = [item.brand, item.model, item.description]
    .filter(Boolean)
    .join(' • ')

  // Build badges
  const badges: RowBadge[] = [
    { label: item.category, variant: 'outline' },
    ...(item.worn ? [{ label: 'Worn', variant: 'secondary' as const }] : []),
    ...(item.consumable ? [{ label: 'Consumable', variant: 'secondary' as const }] : []),
  ]

  // Build metadata string
  const weightDisplay = formatWeightWithUnit(item.weight_grams, weightUnit)
  const totalWeight = formatWeightWithUnit(item.weight_grams * item.quantity, weightUnit)
  const metadata = item.quantity > 1 
    ? `${weightDisplay} each • ${item.quantity} items • ${totalWeight} total`
    : weightDisplay

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    {
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'> = cloneData
        onEdit({ ...newItem, name: `${newItem.name} (Copy)` } as GearItem)
      }
    },
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <GenericRow
      title={item.name}
      subtitle={subtitle}
      badges={badges}
      metadata={metadata}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
    />
  )
}

