import { GenericRow, type RowAction, type RowBadge } from '@/components/shared/GenericRow'
import { Edit2, Trash2, Copy, Eye } from 'lucide-react'
import type { List, GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface ListRowProps {
  list: List
  gearItems: GearItem[]
  weightUnit: WeightUnit
  onView: (list: List) => void
  onEdit: (list: List) => void
  onDelete: (list: List) => void
  onDuplicate: (list: List) => void
}

export function ListRow({ 
  list, 
  gearItems,
  weightUnit,
  onView,
  onEdit, 
  onDelete,
  onDuplicate
}: ListRowProps) {
  // Calculate list stats
  const listGear = gearItems.filter(item => list.gear_ids.includes(item.id))
  const totalWeight = listGear.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
  const baseWeight = listGear
    .filter(item => !item.worn && !item.consumable)
    .reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)

  // Build badges
  const badges: RowBadge[] = []
  if (list.activity_type) {
    badges.push({ label: list.activity_type, variant: 'outline' })
  }

  // Build metadata string
  const itemCount = list.gear_ids.length
  const itemText = itemCount === 1 ? 'item' : 'items'
  const weightDisplay = totalWeight > 0 
    ? formatWeightWithUnit(totalWeight, weightUnit)
    : null
  const baseWeightDisplay = baseWeight > 0 && baseWeight !== totalWeight
    ? formatWeightWithUnit(baseWeight, weightUnit)
    : null

  const metadataParts = [
    `${itemCount} ${itemText}`,
    ...(weightDisplay ? [weightDisplay + ' total'] : []),
    ...(baseWeightDisplay ? [baseWeightDisplay + ' base'] : [])
  ]
  const metadata = metadataParts.join(' • ')

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'View',
      icon: <Eye className="h-4 w-4" />,
      onClick: () => onView(list)
    },
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(list)
    },
    {
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => onDuplicate(list)
    },
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(list),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <GenericRow
      title={list.name}
      description={list.description}
      badges={badges}
      metadata={metadata}
      actions={actions}
      onClick={() => onView(list)}
    />
  )
}

