import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  TableCell,
  TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { MoreHorizontal } from 'lucide-react'

export interface RowAction {
  label: string
  icon: ReactNode
  onClick: () => void
  variant?: 'default' | 'destructive'
  separator?: boolean
}

export interface RowBadge {
  label: string
  variant?: 'default' | 'secondary' | 'destructive' | 'outline'
}

export interface CollectionRowProps {
  title: string
  subtitle?: string
  brand?: string
  category?: RowBadge
  metadata?: string
  secondaryInfo?: ReactNode[]
  actions: RowAction[]
  onClick?: () => void
  className?: string
}

export function CollectionRow({
  title,
  subtitle,
  brand,
  category,
  metadata,
  secondaryInfo = [],
  actions,
  onClick,
  className = ''
}: CollectionRowProps) {
  const handleRowClick = (e: React.MouseEvent) => {
    // Don't trigger onClick if clicking on dropdown trigger
    if ((e.target as Element).closest('[data-dropdown-trigger]')) {
      return
    }
    onClick?.()
  }

  return (
    <TableRow 
      className={`hover:bg-accent/50 transition-colors ${onClick ? 'cursor-pointer' : ''} ${className}`}
      onClick={handleRowClick}
    >
      {/* Main Item Column */}
      <TableCell className="py-3">
        <div className="space-y-1">
