import { CollectionRow, type RowAction, type RowBadge } from '@/components/shared/CollectionRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onClick?: (item: GearItem) => void
}

export function GearRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onClick 
}: GearRowProps) {
  // Build subtitle from model/description
  const subtitle = [item.model, item.description]
    .filter(Boolean)
    .join(' • ')

  // Category badge
  const category: RowBadge = { 
    label: item.category, 
    variant: 'outline' 
  }

  // Build metadata for mobile
  const weightDisplay = formatWeightWithUnit(item.weight_grams, weightUnit)
  const metadata = item.quantity > 1 
    ? `${weightDisplay} each • ${item.quantity} items`
    : weightDisplay

  // Build secondary info for desktop columns (Weight, Qty, Total, Properties)
  const totalWeight = item.weight_grams * item.quantity
  const secondaryInfo = [
    <span>{formatWeightWithUnit(item.weight_grams, weightUnit)}</span>,
    <span>{item.quantity}</span>,
    <span className="font-medium">{formatWeightWithUnit(totalWeight, weightUnit)}</span>,
    <div className="flex items-center gap-1">
      {item.worn && (
        <Badge variant="secondary" className="text-xs">
          Worn
        </Badge>
      )}
      {item.consumable && (
        <Badge variant="secondary" className="text-xs">
          Consumable
        </Badge>
      )}
    </div>
  ]

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    {
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'> = cloneData
        onEdit({ ...newItem, name: `${newItem.name} (Copy)` } as GearItem)
      }
    },
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={item.name}
      subtitle={subtitle}
      brand={item.brand}
      category={category}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
    />
  )
}

