      onClick: () => onDelete(list),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={list.name}
      subtitle={list.description}
      category={category}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      columnClasses={columnClasses}
      actions={actions}
      onClick={() => onView(list)}
