import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  TableCell,
  TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { MoreHorizontal } from 'lucide-react'

export interface RowAction {
  label: string
  icon: ReactNode
  onClick: () => void
  variant?: 'default' | 'destructive'
  separator?: boolean
}

export interface RowBadge {
  label: string
  variant?: 'default' | 'secondary' | 'destructive' | 'outline'
}

export interface CollectionRowProps {
  title: string
  subtitle?: string
  brand?: string
  category?: RowBadge
  metadata?: string
  secondaryInfo?: ReactNode[]
  columnClasses?: string[]
  actions: RowAction[]
  onClick?: () => void
  className?: string
}

export function CollectionRow({
  title,
  subtitle,
  brand,
  category,
  metadata,
  secondaryInfo = [],
  columnClasses = [],
  actions,
  onClick,
  className = ''
}: CollectionRowProps) {
  const handleRowClick = (e: React.MouseEvent) => {
    // Don't trigger onClick if clicking on dropdown trigger
    if ((e.target as Element).closest('[data-dropdown-trigger]')) {
      return
    }
    onClick?.()
  }

  return (
    <TableRow 
      className={`hover:bg-accent/50 transition-colors ${onClick ? 'cursor-pointer' : ''} ${className}`}
      onClick={handleRowClick}
    >
      {/* Main Item Column */}
      <TableCell className="py-3">
        <div className="space-y-1">
          <div className="font-medium text-base leading-tight">
            {title}
          </div>
          {subtitle && (
            <div className="text-sm text-muted-foreground leading-tight">
              {subtitle}
            </div>
          )}
          {brand && (
            <div className="text-xs text-muted-foreground">
              {brand}
            </div>
          )}
          {/* Mobile-only: Show category and metadata inline */}
          <div className="sm:hidden text-xs text-muted-foreground mt-1 flex items-center gap-2">
            {category && (
              <Badge variant={category.variant || 'outline'} className="text-xs py-0">
                {category.label}
              </Badge>
            )}
            {metadata && (
              <>
                {category && <span>•</span>}
                <span>{metadata}</span>
              </>
            )}
          </div>
        </div>
      </TableCell>

      {/* Desktop Category Column */}
      <TableCell className="py-3 hidden sm:table-cell text-right">
        {category && (
          <Badge variant={category.variant || 'outline'} className="text-xs">
            {category.label}
          </Badge>
        )}
      </TableCell>

      {/* Desktop Secondary Info Columns */}
      {secondaryInfo.map((info, index) => (
        <TableCell 
          key={index} 
          className={`py-3 hidden sm:table-cell ${columnClasses[index] || ''}`}
        >
          {info}
        </TableCell>
      ))}

      {/* Actions Column */}
      <TableCell className="py-3 text-right">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              className="h-8 w-8 p-0 hover:bg-accent"
              data-dropdown-trigger="true"
              onClick={(e) => e.stopPropagation()}
            >
              <span className="sr-only">Open menu</span>
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-[160px]">
            {actions.map((action, index) => (
              <div key={index}>
                {action.separator && index > 0 && <DropdownMenuSeparator />}
                <DropdownMenuItem
                  onClick={(e) => {
                    e.stopPropagation()
                    action.onClick()
                  }}
                  className={`cursor-pointer ${
                    action.variant === 'destructive' 
                      ? 'text-destructive focus:text-destructive' 
                      : ''
                  }`}
                >
                  <span className="mr-2">{action.icon}</span>
                  {action.label}
                </DropdownMenuItem>
              </div>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </TableCell>
    </TableRow>
  )
}
